// Manage a dynamic array of destinations and add/update one entry.
// Start with an empty array and num_dests = 0 as required by the API.
size_t num_dests = 0;
cups_dest_t *dests = nullptr;

// name: required non-NULL string; instance: optional.
std::string name_s = FUZZ_PARAM_STR();
if (name_s.empty()) { FUZZ_BAIL(); }
const char *name = name_s.c_str();

// Randomly choose to provide or omit an instance name.
std::string instance_s = FUZZ_PARAM_STR();
const char *instance = (instance_s.size() % 2) ? instance_s.c_str() : (const char *)nullptr;

// Add the destination. The function may reallocate *dests.
num_dests = cupsAddDest(name, instance, num_dests, &dests);

// Record the current count for downstream stubs.
FUZZ_SET_ATTR_INT(dests, "num", (int)num_dests);
// Expose dests as an output so the runtime can manage and reuse it.

// Ensure dinfo corresponds to dest using an attribute set by the creator of dinfo.
void *parent = FUZZ_GET_ATTR_PTR(dinfo, "dest");
if (!parent || parent != (void *)dest) { FUZZ_BAIL(); }

// Start with an empty options array as required by the API contract.
size_t num_options = 0;
cups_option_t *options = nullptr;

// Build a media selection; populate minimally valid values.
cups_media_t media = {};
// Names: keep within 127 chars to fit into fixed arrays once copied by CUPS helpers.
std::string mname = FUZZ_PARAM_STR(); if (mname.size() > 120) mname.resize(120);
strncpy(media.media, mname.c_str(), sizeof(media.media) - 1);
std::string mcolor = FUZZ_PARAM_STR(); if (mcolor.size() > 120) mcolor.resize(120);
strncpy(media.color, mcolor.c_str(), sizeof(media.color) - 1);
std::string msrc = FUZZ_PARAM_STR(); if (msrc.size() > 120) msrc.resize(120);
strncpy(media.source, msrc.c_str(), sizeof(media.source) - 1);
std::string mtype = FUZZ_PARAM_STR(); if (mtype.size() > 120) mtype.resize(120);
strncpy(media.type, mtype.c_str(), sizeof(media.type) - 1);

// Dimensions/margins: ensure positive and within a reasonable range.
media.width  = (int)(*FUZZ_PARAM(unsigned int) % 20000u) + 1;   // hundredths of mm
media.length = (int)(*FUZZ_PARAM(unsigned int) % 20000u) + 1;
media.left   = (int)(*FUZZ_PARAM(unsigned int) % 1000u);
media.right  = (int)(*FUZZ_PARAM(unsigned int) % 1000u);
media.top    = (int)(*FUZZ_PARAM(unsigned int) % 1000u);
media.bottom = (int)(*FUZZ_PARAM(unsigned int) % 1000u);

// Select flags from documented cups_media_flags_t values.
unsigned flags = (unsigned)(*FUZZ_PARAM(unsigned int) & (CUPS_MEDIA_FLAGS_BORDERLESS | CUPS_MEDIA_FLAGS_DUPLEX | CUPS_MEDIA_FLAGS_EXACT | CUPS_MEDIA_FLAGS_READY));

// http may be CUPS_HTTP_DEFAULT or a live connection; we accept provided http.
num_options = cupsAddDestMediaOptions(http, dest, dinfo, flags, &media, num_options, &options);

// Track count for downstream.
FUZZ_SET_ATTR_INT(options, "num", (int)num_options);
// Keep association for potential conflict checks.
FUZZ_SET_ATTR_PTR(options, "dest", (void *)dest);
FUZZ_SET_ATTR_PTR(options, "dinfo", (void *)dinfo);
// Return options for reuse.

// Start from an empty options array.
size_t num_options = 0;
cups_option_t *options = nullptr;

// Required non-NULL name.
std::string name_s = FUZZ_PARAM_STR();
if (name_s.empty()) { FUZZ_BAIL(); }
const char *name = name_s.c_str();

// Integer value.
long value = (long)(*FUZZ_PARAM(int));

num_options = cupsAddIntegerOption(name, value, num_options, &options);

FUZZ_SET_ATTR_INT(options, "num", (int)num_options);
// Return the options array so it can be extended by subsequent stubs.

