if (cn.empty()) { cn = "x"; }
(void)cupsAreCredentialsValidForName(cn.c_str(), creds.c_str());
// No persistent outputs required.

// Require a previously created job ID associated with this dest.
int job_id = FUZZ_GET_ATTR_INT(dest, "job_id");
if (job_id <= 0) { FUZZ_BAIL(); }

// Invoke cancellation; caller will interpret ipp_status_t elsewhere.
