cups_dest_t *dests = nullptr;

num_dests = cupsCopyDest(dest, num_dests, &dests);

FUZZ_SET_ATTR_INT(dests, "num", (int)num_dests);
// Expose dests so future stubs can add/remove or set default.

// Ensure dinfo belongs to dest.
void *parent = FUZZ_GET_ATTR_PTR(dinfo, "dest");
if (!parent || parent != (void *)dest) { FUZZ_BAIL(); }

// Prepare a small options array (may be empty) for baseline.
size_t num_options = 0;
cups_option_t *options = nullptr;

// New option/value to check must be non-NULL strings.
std::string new_opt = FUZZ_PARAM_STR();
std::string new_val = FUZZ_PARAM_STR();
if (new_opt.empty() || new_val.empty()) { FUZZ_BAIL(); }

// Outputs for conflicts/resolved; the function will allocate these if any.
size_t num_conflicts = 0, num_resolved = 0;
cups_option_t *conflicts = nullptr, *resolved = nullptr;

(void)cupsCopyDestConflicts(http, dest, dinfo, num_options, options, new_opt.c_str(), new_val.c_str(), &num_conflicts, &conflicts, &num_resolved, &resolved);

// Free any allocations returned by the API.
if (conflicts) cupsFreeOptions(num_conflicts, conflicts);
if (resolved) cupsFreeOptions(num_resolved, resolved);
if (options) cupsFreeOptions(num_options, options);
// No persistent outputs.

// dst must be a writable buffer; src must be a NUL-terminated string.
char dst[128];
std::string src = FUZZ_PARAM_STR();
(void)cupsCopyString(dst, src.c_str(), sizeof(dst));
// No outputs.

// Validate that dinfo corresponds to dest (must have been set by the creator of dinfo).
